#include <iostream>

int suma_iterativa(int tope) {
    int total = 0;
    for (int valor = 1; valor <= tope; ++valor) {
        total = total + valor;
    }
    return total;
}

int suma_recursiva(int tope) {
    if (tope == 0) {
        return 0;
    }
    return tope + suma_recursiva(tope - 1);
}

int main() {
    std::cout << suma_iterativa(2) << " " << suma_recursiva(2);
    return 0;
}

