#include <iostream>

int suma_iterativa(int tope) {
    int total = 0;
    for (int valor = 1; valor <= tope; ++valor) {
        total = total + valor;
    }
    return total;
}

int suma_recursiva(int tope) {
    if (tope == 0) {
        return 0;
    }
    return tope + suma_recursiva(tope - 1);
}

int main() {
    const int tope = 3;
    if ((tope < 0) || (tope > 8)) {
        std::cout << "Fuera del dominio";
    } else {
        const int iterativa = suma_iterativa(tope);
        const int recursiva = suma_recursiva(tope);
        std::cout << iterativa << " " << recursiva;
    }
    return 0;
}
